import sys

def mono_opt(n):
    s = list(str(n))
    mark = len(s)
    for i in range(len(s) - 1, 0, -1):
        if s[i] < s[i - 1]:
            s[i - 1] = str(int(s[i - 1]) - 1)
            mark = i
    if mark < len(s):
        for i in range(mark, len(s)):
            s[i] = '9'
    return int(''.join(s))

if __name__ == '__main__':
    n = int(sys.stdin.readline().strip())
    print(mono_opt(n))

import sys

def mono_best(n):
    s = list(str(n))
    n_len = len(s)
    for i in range(n_len - 1, 0, -1):
        if s[i] < s[i - 1]:
            s[i - 1] = str(int(s[i - 1]) - 1)
            mark = i
    if 'mark' not in dir():
        return n
    for i in range(mark, n_len):
        s[i] = '9'
    return int(''.join(s))

if __name__ == '__main__':
    n = int(sys.stdin.readline().strip())
    print(mono_best(n))
